insert into public.mushroom_growth_conditions (slug,best_after,soil_conditions,microhabitat,foraging_difficulty,foraging_tips,source,verified) values 
('agaricus_silvaticus','Hauptzeit Aug–Okt, schubweise ca. 5–10 Tage nach ergiebigem Regen bei milden 10–16 °C; erscheint oft truppweise und kann nach jedem Regenschub neu nachwachsen.','Bevorzugt frische bis feuchte, eher saure, humus- und nadelstreureiche Waldböden; meidet stark kalkige Standorte.','Streu- und Humuszersetzer (saprobiontisch, keine Mykorrhiza), typisch im Nadelstreu unter Fichten, auch in Misch- und Bergwäldern; oft bei Moos und Fichtennadel-Polstern.','mittel','Bräunlich-faserig geschuppter Hut, Fleisch und Lamellen-Region röten beim Anschneiden/Reiben deutlich (Schnittprobe wichtig). Geruch angenehm pilzig, NICHT chemisch/tintig. Sicheres Ausschlusskriterium: keine Knolle mit häutiger Scheide am Stielgrund – sonst Verwechslungsgefahr mit jungen, tödlichen Amanita (Knollenblätterpilz) prüfen. Gelb anlaufende, karbolartig riechende Champignons (A. xanthodermus) meiden.','123pilze; DGfM; SwissFungi (Datenbank Schweiz); gängige Pilzführer (Laux, Gerhardt)',false),
('agaricus_silvicola','Hauptzeit Aug–Okt (bis Nov in milden Lagen), schubweise rund 1 Woche nach kräftigem Regen bei 10–16 °C; einzeln bis in kleinen Gruppen.','Frische, humose Waldböden, kalkmeidend bis neutral; in nährstoffreicher Nadel- und Laubstreu.','Saprobiontischer Streuzersetzer (keine Mykorrhiza), gern im Nadelstreu unter Fichten sowie in Mischwäldern; Standorttyp: krautarmer, schattiger Waldboden.','experte','Weisslich-cremiger, schlanker Hut, gilbt bei Druck/Reibung leicht goldgelb; deutlicher Anis-/Bittermandel-Geruch. Lamellen jung blass-rosa, später schokobraun – NIE weiss bleibend. WICHTIG: weisse, weisslamellige Verwechslung mit tödlichem Weissen Knollenblätterpilz (Amanita) – immer auf Stielbasis ohne häutige Scheide/Knolle und auf rosa-braune Lamellen achten. Karbolartiger Geruch + chromgelbes Anlaufen an der Stielbasis = giftiger Karbol-Egerling, meiden.','123pilze; DGfM; SwissFungi (Datenbank Schweiz); gängige Pilzführer (Laux, Gerhardt)',false),
('amanita_caesarea','Hauptzeit Jul–Okt nach sommerlichen Gewitterregen, ca. 1–2 Wochen nach Niederschlag bei warmen 18–25 °C; wärmebedürftig, in der Schweiz selten und nur an wenigen wärmebegünstigten Südlagen (Tessin/Südalpen).','Eher trockene bis frische, saure bis schwach kalkige, durchlässige Böden in wärmebegünstigten Lagen.','Mykorrhiza mit Eiche, Edelkastanie, selten Buche/Kiefer; lichte, warme Laub-/Kastanienwälder, Hangwälder mit guter Besonnung.','experte','Leuchtend orange-roter Hut, dottergelbe (nicht weisse!) Lamellen und gelber Stiel mit gelbem, häutigem Ring – plus weisse, sackartige Volva am Stielgrund. ACHTUNG Eistadium: junge, im weissen Hüllei steckende Exemplare sind kaum vom tödlichen Grünen Knollenblätterpilz oder vom Fliegenpilz zu unterscheiden – nie unreife „Eier“ sammeln. In der Schweiz vielerorts geschützt/selten – Bestand schonen. Nur bei voll aufgeschirmtem, eindeutig gelbem Lamellen-/Stielbild ernten.','123pilze; DGfM; SwissFungi (Datenbank Schweiz); gängige Pilzführer (Laux, Gerhardt)',false),
('amanita_crocea','Hauptzeit Jul–Okt (vereinzelt ab Jun und bis Nov), ca. 1–2 Wochen nach ergiebigem Regen bei 12–18 °C; erscheint schubweise einzeln bis in kleinen Gruppen.','Bevorzugt saure, eher feuchte Wald- und Moorrandböden; auch auf sandig-humosen Standorten, kalkmeidend.','Mykorrhiza vor allem mit Birke, daneben Eiche, Erle, Hainbuche, Hasel und Fichte; in Laub-, Misch- und Nadelwäldern, gern an feuchten, moosigen Stellen.','experte','Orange-ockerfarbener, ungeriefter-mittiger Hut mit deutlich gerieftem Rand, KEIN Ring am glatten, orange genatterten Stiel, weisse, hohe, oft orange überlaufene Scheide (Volva) am Grund. Roh giftig – nur gut durchgegart geniessbar (bedingt essbar). Da Gattung Amanita: tödliche Knollenblätterpilze haben einen Ring – ringloser Streifling mit gerieftem Hutrand und Volva ist Bestimmungsschlüssel. Im Zweifel nicht sammeln; Volva immer vollständig ausgraben.','123pilze; DGfM; SwissFungi (Datenbank Schweiz); gängige Pilzführer (Laux, Gerhardt)',false),
('amanita_fulva','Hauptzeit Jul–Okt (ab Jun möglich), ca. 1–2 Wochen nach ergiebigem Regen bei 12–18 °C; einer der häufigsten Streiflinge, erscheint schubweise.','Saure, feuchte Böden, oft an Moorrändern und in feuchten Nadel-/Mischwäldern; kalkmeidend.','Mykorrhiza mit Birke, Buche, Eiche, Fichte und Kiefer; in Laub-, Misch- und Nadelwald sowie Moorgebieten, gern an feuchten, moosigen Plätzen.','experte','Rotbrauner bis fuchsbrauner Hut mit deutlich gerieftem Rand, glatter, ringloser, blass rötlichbrauner Stiel, hohe weisse, oft rostbraun gefleckte Scheide (Volva) am Grund. Roh giftig – nur gut durchgegart geniessbar. Gattung Amanita: ringlos + gerieft + Volva unterscheidet vom tödlichen, beringten Knollenblätterpilz. Stielbasis stets komplett ausgraben, um die Volva zu prüfen; im Zweifel stehen lassen.','123pilze; DGfM; SwissFungi (Datenbank Schweiz); gängige Pilzführer (Laux, Gerhardt)',false),
('amanita_strobiliformis','Hauptzeit Jul–Okt nach warmen Sommerregen, ca. 1–2 Wochen nach Niederschlag bei warmen 16–22 °C; wärmeliebend, einzeln stehend.','Bevorzugt kalkreiche, basenreiche, eher trocken-warme Böden; auf Kalk und in nährstoffreichen Parkböden.','Mykorrhiza mit Eiche, Buche, Linde, selten Kiefer; in wärmebegünstigten Laubwäldern, Parkanlagen, an Weg- und Waldrändern auf Kalk.','experte','Grosser, weisslicher Hut mit groben, pyramidalen, leicht abwischbaren grauweissen Hüllflocken, beringter Stiel mit knolliger, von gürtelartigen Flockenresten umgebener Basis (keine häutige Scheide). Bedingt essbar – minderwertig und wegen Verwechslungsgefahr in der Gattung Amanita nur für Kenner. Sicher abgrenzen gegen den giftigen Pantherpilz und den Fliegenpilz; bei flockigem weissem Wulstling im Zweifel grundsätzlich stehen lassen.','123pilze; DGfM; SwissFungi (Datenbank Schweiz); gängige Pilzführer (Laux, Gerhardt)',false),
('amanita_vaginata','Hauptzeit Juni–Oktober, oft schon im Frühsommer; erscheint einzeln und schubweise rund 1–2 Wochen nach kräftigem Regen bei milden 14–20 °C. Verträgt wärmere, trockenere Phasen besser als viele andere Streiflinge und kommt nach Sommergewittern rasch.','Wächst auf eher sauren bis neutralen, mässig frischen Böden; toleriert auch sandige und nährstoffärmere Standorte. Mag mässige Bodenfeuchte, keine Staunässe.','Mykorrhiza-Partner mit Laub- und Nadelbäumen – v. a. Birke, Buche, Eiche, Fichte und Kiefer; auch an Waldrändern, in Parks und unter eingestreuten Bäumen. Zeigerbäume: Birke und Buche auf sauren Böden.','experte','Nur roh giftig, gegart bedingt essbar – wegen Zugehörigkeit zur kritischen Gattung Amanita ausschliesslich für Erfahrene. Kennzeichen: grauer, am Rand deutlich gerillter ("gestreifter") Hut, KEIN Ring am Stiel, dafür eine häutige, weisse Scheide (Volva) am Stielgrund – immer komplett ausgraben und die Stielbasis prüfen. Lebensgefährliche Verwechslung mit jungen Knollenblätterpilzen (Amanita) und grauen Wulstlingen ausschliessen; im Zweifel stehen lassen.','123pilze, DGfM, Pilzführer Schweiz (SwissFungi)',false),
('boletus_pinophilus','Zweigipflige Saison: ein erster Schub im Früh-/Hochsommer (Juni–Juli) und ein Hauptschub im Herbst (September–Oktober); erscheint typischerweise 1–2 Wochen nach ergiebigem Regen bei Bodentemperaturen um 12–18 °C. In Bergwäldern oft etwas später als der Gemeine Steinpilz.','Bevorzugt nährstoffarme, saure bis neutrale, sandige und gut drainierte Böden; trockene bis mässig frische Standorte, keine Staunässe.','Mykorrhiza-Partner v. a. mit Kiefer (Pinus), selten Fichte; in Kiefern- und Bergnadelwäldern, gern auf höheren Lagen. Zeigerstandort: lichte Kiefernbestände auf Sand, oft am Wegrand und an grasigen Lichtungen.','mittel','Hervorragender Speisepilz, Verwechslungsrisiko gering, aber Steinpilz-Sicherheit nötig. Erkennung: rotbraun-kupferfarbener, oft fein bereifter Hut, weisses unveränderliches Röhrenlager (jung weiss, später gelbgrün), heller netziger Stiel; Fleisch bleibt beim Schnitt weiss. Abgrenzung zum bitteren Gallenröhrling (rosa Röhren, bitterer Geschmack – Kostprobe an der Röhrenspitze) und zum blau anlaufenden Hexenröhrling beachten.','123pilze, SwissFungi, Pilzführer Schweiz',false),
('butyriboletus_appendiculatus','Wärmeliebende Sommerart: Hauptzeit Juli–September (vereinzelt ab Juni), nach warmen Sommergewittern rund 1–2 Wochen verzögert; braucht warme Böden über ~16 °C und erscheint in trocken-warmen Sommern oft früher als andere Röhrlinge.','Wächst bevorzugt auf warmen, basischen bis kalkreichen, eher frischen Böden in Tief- und Hügellagen; meidet stark saure, kalte Standorte.','Mykorrhiza-Partner mit Laubbäumen, v. a. Eiche (Quercus) und Buche (Fagus); in lichten, warmen Eichen-/Buchenwäldern und an deren Rändern. Zeigerstandort: thermophile Kalk-Laubwälder, oft an krautreichen Hängen.','experte','Guter Speisepilz, aber sichere Abgrenzung innerhalb der Dickröhrlinge nötig. Merkmale: hell ocker- bis semmelfarbener Hut, leuchtend gelbe Röhren und gelbes Fleisch, das nur schwach bläulich anläuft, feines gelbes Stielnetz, oft "angehängte" wurzelartige Stielbasis (Namensgeber). Strikt vom giftigen Satansröhrling (rote Poren, weisslicher Hut, kalkliebend, gleicher Standort!) und anderen rotporigen Dickröhrlingen trennen – nur Exemplare mit gelben Poren nehmen.','123pilze, DGfM, SwissFungi',false),
('cantharellus_pallens','Lange Saison von Juni bis September (in milden Jahren bis Oktober); erscheint schubweise einige Tage bis 2 Wochen nach durchdringendem Landregen bei gleichmässiger Bodenfeuchte und 13–18 °C. Reagiert auf Feuchtigkeit etwas träger als Sommerpilze, dafür über Wochen ergiebig an denselben Stellen.','Bevorzugt kalkhaltige bis neutrale, humose, gleichmässig frische Waldböden; mag Moos- und Laubstreuauflagen, keine Trockenheit.','Mykorrhiza-Partner v. a. mit Rotbuche (Fagus) und anderen Laubbäumen; in Buchen- und Buchenmischwäldern, gern in Moospolstern und an leicht beschatteten Hängen. Zeigerstandort: krautarme Buchenhallenwälder auf Kalk.','mittel','Sehr guter Speisepilz, wächst meist gesellig in Trupps. Erkennung: blass cremeweiss bereifter Hut (typische weissliche Reifschicht, beim Reiben gilbend), herablaufende, dicke gegabelte Leisten (KEINE echten Lamellen), voller Stiel, angenehm fruchtiger Aprikosengeruch. Hauptverwechsler ist der giftige Falsche Pfifferling (echte, dünne, dicht stehende Lamellen, orangefarben) sowie der Ölbaumtrichterling – immer auf Leisten statt Lamellen achten.','123pilze, SwissFungi, Pilzführer Schweiz',false),
('chlorophyllum_rhacodes','Hauptzeit Spätsommer bis Spätherbst, Juli–November mit Schwerpunkt September–Oktober; erscheint in Hexenringen oder Gruppen rund 1–2 Wochen nach Regen bei 10–18 °C, oft bis zum ersten Frost. Profitiert von nährstoffreichen, gestörten Standorten und kommt auch in trockeneren Phasen noch.','Wächst auf nährstoffreichen, humosen bis stickstoffreichen Böden; gerne auf Kompost, Mulch, Nadelstreu und gestörtem Boden, mässig frisch.','Saprobiont (Folgezersetzer, kein Mykorrhizapilz) auf Streu und nährstoffreichem Boden; in Nadel-/Mischwäldern, Parks, Gärten und an Komposthaufen. Zeigerstandort: ruderale, gedüngte Stellen, Wegränder, Gartenränder.','mittel','Guter Speisepilz (nur Hüte, gut durchgaren), wächst oft in auffälligen Gruppen. Merkmale: grobschuppiger Hut, KEIN genatterter Stiel (glatt, einfacher verschiebbarer Ring), und – entscheidend – das weisse Fleisch verfärbt sich beim Anschneiden/Reiben deutlich safran-orangerot bis bräunlich. Achtung: rohe sowie ähnliche Arten (Chlorophyllum brunneum/venenatum) können Magen-Darm-Beschwerden auslösen; nicht mit dem giftigen, in Gärten wachsenden Grünsporigen Riesenschirmling (Chlorophyllum molybdites, grünlicher Sporenstaub) verwechseln. Vom essbaren Parasol durch fehlende Stielnatterung trennen.','123pilze, DGfM, SwissFungi',false),
('chroogomphus_rutilus','Spätsaison Juli–Oktober mit Schwerpunkt im Herbst (September–Oktober); erscheint einzeln bis gesellig rund 1–2 Wochen nach Regen bei kühleren 10–16 °C, häufig zusammen mit Schmierröhrlingen (Suillus) unter Kiefern und oft bis in den Spätherbst.','Bevorzugt saure, nährstoffarme, sandige und gut drainierte Böden; trockene bis mässig frische Kiefernstandorte.','An Kiefer (zweinadelige Pinus) gebunden, biotroph bzw. mykoparasitisch mit Schmierröhrlingen (Suillus) verbunden; in Kiefern- und sauren Nadelwäldern, oft direkt neben Butterpilzen. Zeigerstandort: moosige Kiefernforste auf Sand, wo auch Suillus wächst.','mittel','Bedingt essbar und kulinarisch wenig ergiebig (färbt Gerichte violett), aber leicht zu bestimmen und verwechslungsarm. Merkmale: kupfer- bis weinrotbrauner, schmieriger Hut, weit herablaufende, dicke, olivlich-braune bis weinrote Lamellen, spitz zulaufender Stiel ohne echten Ring (nur faserige Velumzone); Fleisch lachs-/safranrosa, beim Garen dunkelnd. Hauptmerkmal Standort unter Kiefer neben Suillus. Nicht mit dem ähnlichen Filzigen Gelbfuss verwechseln, dieser ist aber ebenfalls ungefährlich.','123pilze, SwissFungi, Pilzführer Schweiz',false),
('clitocybe_odora','Spätsommer bis Spätherbst, Hauptzeit Sept-Okt (Aug-Nov). Erscheint gesellig in der Streu rund 1-2 Wochen nach ergiebigem Herbstregen bei milden 8-15 °C; schiebt schubweise nach Niederschlagsperioden.','Frische, humose Wald- und Streuböden; sowohl auf sauren als auch auf kalkhaltigen Standorten. Bevorzugt feuchte, schattige Lagen, meidet dauernd nasse Stellen.','Saprob (kein Mykorrhiza-Partner) in der Laub- und Nadelstreu von Laub-, Nadel- und Mischwäldern, gern entlang von Wurzeln und an Wegrändern. Zeigerumfeld: Buche und Fichte, krautreiche Waldsäume.','mittel','Eindeutigstes Merkmal ist der starke, süssliche Anis-/Marzipangeruch zusammen mit dem blassgrün-blaugrünen Hut - diese Kombination hat kein giftiger Pilz. Trotzdem mit Vorsicht: junge oder verblasste Exemplare können weisslichen, giftigen Trichterlingen ähneln, daher immer den Anisgeruch und die am Stiel herablaufenden Lamellen prüfen. Wird nur als sparsamer Würzpilz verwendet, nicht als Hauptspeisepilz.','123pilze, SwissFungi, DGfM, gängige Pilzführer - mykologisches Standardwissen, vorsichtig formuliert',false),
('clitopilus_prunulus','Sommer bis Herbst, Hauptzeit Aug-Sept (Jul-Nov). Fruchtkörper erscheinen einzeln bis gesellig einige Tage bis ~1-2 Wochen nach durchdringendem Regen bei warmen 12-18 °C.','Nährstoffreiche, eher kalkhaltige bis neutrale, gut durchfeuchtete Wald- und Parkböden; meidet stark saure, magere Standorte.','Saprob auf nackten Erdstellen, an Waldwegen, Böschungen und Waldrändern in Laub-, Nadel- und Mischwald sowie Parkanlagen; oft an lichten, grasigen Stellen. Häufig in der Nähe von Steinpilz-Standorten ("Steinpilz-Wegweiser").','experte','ACHTUNG hohe Verwechslungsgefahr: der weisse Hut mit anfangs weissen, im Alter rosa werdenden, herablaufenden Lamellen ähnelt tödlich giftigen weissen Trichterlingen (Clitocybe rivulosa/dealbata) und Risspilzen. Sicheres Merkmal ist der starke, frische Mehl-/Gurkengeruch und das rosa Sporenpulver (Sporenabwurf machen!). Nur für Erfahrene; im Zweifel stehen lassen.','123pilze, SwissFungi, DGfM, gängige Pilzführer - mykologisches Standardwissen, vorsichtig formuliert',false),
('coprinellus_micaceus','Nahezu ganzjährig (Frühjahr bis Spätherbst, Schwerpunkt Apr-Nov), bei mildem Wetter auch im Winter. Erscheint büschelig schon 2-5 Tage nach Regen und vergeht rasch; am besten morgens jung sammeln, da die Hüte innerhalb eines Tages zertintlern.','Feuchte, humus- und holzreiche Böden; anspruchslos bezüglich pH. Braucht morsches Holz oder vergrabene Holzreste im Untergrund.','Saprob (Holzzersetzer) in dichten Büscheln an und über morschem Laubholz, an Stümpfen, Wurzeln und auf Rasen über vergrabenem Holz in Laub-/Mischwald, Gärten und Parks. Kein Mykorrhiza-Partner.','mittel','Gut kenntlich am büscheligen Wuchs, dem eiförmig-glockigen, fein gerieften Hut mit den glimmerartigen, glitzernden Velumkörnchen (am besten an jungen, trockenen Exemplaren sichtbar) und am späteren Zertintlern der Lamellen. Nur ganz junge, noch geschlossene Hüte sammeln und rasch verarbeiten; vorsichtshalber ohne Alkohol geniessen.','123pilze, SwissFungi, DGfM, gängige Pilzführer - mykologisches Standardwissen, vorsichtig formuliert',false),
('coprinopsis_atramentaria','Frühjahr bis Spätherbst, Hauptzeit Mai-Okt (Apr-Nov). Schiebt büschelig wenige Tage nach kräftigem Regen bei mildem Wetter; Fruchtkörper zerfliessen schnell, daher jung und zeitnah ernten.','Nährstoff- und humusreiche, feuchte Böden in Siedlungsnähe; anspruchslos, oft auf gestörten, gedüngten Standorten. Holzreste im Untergrund begünstigen das Wachstum.','Saprob in dichten Büscheln über vergrabenem Holz, an Stümpfen, Wegrändern, in Gärten, Parks und Laub-/Mischwald auf humusreichem Boden. Kein Mykorrhiza-Partner.','mittel','Kenntlich am büscheligen Wuchs, dem graubraunen, oben oft schwach schuppigen Faltenhut und dem typischen Zertintlern von unten her. WICHTIG: enthält Coprin - in Kombination mit Alkohol (auch noch 1-2 Tage davor/danach) kommt es zum Antabus-Effekt (Übelkeit, Herzrasen, Rötung). Nur jung, gut durchgegart und strikt alkoholfrei verzehren.','123pilze, SwissFungi, DGfM, gängige Pilzführer - mykologisches Standardwissen, vorsichtig formuliert',false),
('craterellus_lutescens','Herbstpilz, Hauptzeit Sept-Okt (Aug-Nov bis zum ersten Frost). Erscheint in dichten Truppen etwa 1-2 Wochen nach anhaltendem Herbstregen bei kühlen 8-14 °C; an guten Stellen jahrelang am selben Fleck.','Kalkhaltige bis schwach saure, feuchte, moosige und torfige Nadelwaldböden; bevorzugt dauerfeuchte, schattige Lagen.','Mykorrhiza-Partner v.a. Fichte (auch Kiefer/Nadelbäume) in feuchten, moosigen Nadel- und Mischwäldern; oft in Moospolstern, an Bachsäumen und in Mulden. Zeigerumfeld: dichte Moosdecken unter Fichten auf Kalk.','mittel','In Truppen wachsend, daher beim Fund meist reichlich. Erkennbar am trichterig-durchbohrten, graubraunen Hut, den fast glatten bis schwach geaderten Leisten und dem leuchtend gelb-orangen, hohlen Stiel sowie dem kräftig-aromatischen Geruch. Verwechslung praktisch nur mit anderen essbaren Leistlingen/Trompetenpfifferlingen (C. tubaeformis) - kein gefährlicher Doppelgänger.','123pilze, SwissFungi, DGfM, gängige Pilzführer - mykologisches Standardwissen, vorsichtig formuliert',false),
('cyanoboletus_pulverulentus','Sommer bis Herbst, Hauptzeit Jul-Sept (Jun-Okt). Erscheint einzeln bis gesellig rund 1-2 Wochen nach ergiebigem Regen bei warmen 15-20 °C, gern an feuchten, schattigen Stellen.','Frische bis feuchte, eher saure bis neutrale Laubwaldböden; oft an verdichteten, feuchten Stellen an Wegen und Gräben.','Mykorrhiza-Partner v.a. Buche und Eiche (auch Edelkastanie, diverse Laubbäume) in Laub- und Mischwäldern, Parks, an Wegrändern und im Gras. Zeigerumfeld: feuchte Buchen-/Eichenbestände.','mittel','Unverwechselbares Merkmal: bei der geringsten Berührung oder beim Anschnitt verfärben sich Poren, Fleisch und Stiel sofort intensiv tinten- bis schwarzblau. Hut olivbraun, Poren jung gelb. Gilt nur als bedingt essbar, da er Schwermetalle (Cadmium) anreichern kann - daher nur junge Exemplare und in Massen geniessen, nicht in belasteten Lagen sammeln.','123pilze, SwissFungi, DGfM, gängige Pilzführer - mykologisches Standardwissen, vorsichtig formuliert',false),
('cyclocybe_aegerita','Hauptzeiten Frühling (April–Juni) und Herbst (September–November); erscheint schubweise einige Tage bis ~2 Wochen nach feucht-milder Witterung mit Temperaturen um 10–20 °C. Profitiert von milden, regenreichen Perioden und kann bei frostfreiem Wetter auch in milden Wintern büschelig nachschieben.','Standort-unabhängig vom Boden, da holzbewohnend (saprob); bevorzugt feuchte, nährstoffreiche Auen- und Parkstandorte mit reichlich Laubholz-Totholz.','Saprob (kein Mykorrhiza-Partner): büschelig an Strünken und morschem Stammholz von Pappel, seltener Weide, Holunder, Ahorn und anderen Laubbäumen. Typisch in Auwald, Parkanlagen und Flussufern.','mittel','Büschelig an Laubholz-Strünken (v. a. Pappel) suchen; Hut jung halbkugelig-braun und glatt, im Alter ockerblass und feinrissig aufreißend. Sicheres Merkmal: häutiger Ring am Stiel und tabakbrauner Sporenstaub. Vorsicht vor braunsporigen Holzbewohnern wie dem tödlichen Gifthäubling (Galerina) – bei Ringpilzen an Holz immer Sporenfarbe und Habitus genau prüfen.','123pilze, DGfM, SwissFungi; gängige Pilzführer',false),
('fistulina_hepatica','Spätsommer bis Herbst, Hauptzeit August–Oktober; einzelne Fruchtkörper ab feucht-warmer Witterung, etwa 1–2 Wochen nach Regen bei wärmeren Temperaturen. Wächst langsam über Wochen am selben Baum, daher kein klassisches Massen-Schubverhalten.','Bodenunabhängig (holzbewohnend, schwächeparasitisch/saprob); bevorzugt warme, thermophile Laubmischwälder auf eher trockenen, sonnenexponierten Lagen.','Schwächeparasit/Saprob an lebenden und toten Stämmen: meist an der Stammbasis oder am unteren Stamm alter Eichen, seltener an Edelkastanie. Zeigt alte, vitale Eichenbestände an.','anfaenger','An der Basis alter Eichen nach dem unverkennbaren zungen- bis leberförmigen, blutrot bis leberbraun gefärbten Konsolenpilz suchen. Frische Schnittfläche ist rot marmoriert und sondert einen rötlichen Saft ab; die Röhrenschicht lässt sich einzeln ablösen. Nur jung und essbar verwerten – durch hohen Säuregehalt eigenwillig sauer (bedingt essbar). Praktisch verwechslungsfrei.','123pilze, DGfM, SwissFungi; gängige Pilzführer',false),
('flammulina_velutipes','Spätherbst bis Vorfrühling (Oktober–März), echter Winterpilz; erscheint oft während oder kurz nach milderen Phasen zwischen Frostperioden. Ein Frost-Tau-Wechsel mit feuchtem, mildem Wetter um 0–10 °C löst die Schübe aus; verträgt Durchfrieren und treibt danach erneut aus.','Bodenunabhängig (saprob, holzbewohnend); typisch in feuchten Laubwäldern, an Bach- und Flussufern, in Parks und Gärten.','Saprob: büschelig an Totholz, Strünken, Stämmen und Ästen von Laubbäumen (v. a. Weide, Pappel, Esche, Ulme, Buche). Oft an absterbenden oder geschwächten lebenden Bäumen.','experte','Büschel an Laubholz im Winter suchen: orangebrauner, schmieriger Hut und vor allem der namensgebende samtig-dunkelbraune bis schwarze Stiel im unteren Teil. ACHTUNG: Der tödlich giftige Gifthäubling (Galerina marginata) wächst im selben Holz-Habitat und ähnelt jungen Exemplaren – Samtfuß hat weißen Sporenstaub und KEINEN Ring, Galerina rostbraunen Sporenstaub und einen Ring. Im Zweifel Sporenabwurf machen; nur für Geübte.','123pilze, DGfM, SwissFungi; gängige Pilzführer',false),
('gomphidius_glutinosus','Sommer bis Herbst, Hauptzeit Juli–Oktober; erscheint einige Tage bis ~2 Wochen nach ergiebigem Regen bei kühl-feuchter Witterung um 10–16 °C, häufig parallel zur Fichten-Steinpilz-Saison in montanen Lagen.','Saure bis neutrale, eher frische bis feuchte Nadelwaldböden; oft auf Rohhumus über sauren Silikat- oder Moränenböden in Berglagen.','Mykorrhiza mit Fichte (Picea); typisch in montanen Fichten- und Bergmischwäldern, oft moosreich. Folgt der Fichte als verlässlichem Zeigerbaum.','mittel','Unter Fichten im Moos suchen; stark schleimig-glänzender grau- bis purpurbrauner Hut, weit am Stiel herablaufende, jung weißliche, im Alter grau-schwärzliche Lamellen und eine leuchtend gelbe Stielbasis. Schwarzer Sporenstaub. Vor dem Verzehr die schleimige Huthaut abziehen (bedingt essbar). Recht charakteristisch, dennoch Schleimpilz-typische Merkmale sorgfältig abgleichen.','123pilze, DGfM, SwissFungi; gängige Pilzführer',false),
('grifola_frondosa','Spätsommer bis Herbst, Hauptzeit August–Oktober (bis November); erscheint nach längeren feucht-warmen Perioden, oft 1–2 Wochen nach kräftigem Regen bei 15–22 °C. Wächst über mehrere Tage zu einem großen Fruchtkörper heran und kann jahrelang am selben Baum wiederkehren.','Bodenunabhängig (holzbewohnend, schwächeparasitisch/saprob am Wurzel- und Stammfuß); bevorzugt warme, eher basenreiche Laubwaldstandorte.','Schwächeparasit/Saprob an der Stammbasis und im Wurzelbereich alter Eichen, seltener Buche, Kastanie oder Linde. Zeigt alte, anbrüchige Eichen an; oft jahrelang am gleichen Baumstumpf.','mittel','Am Fuß alter Eichen nach der großen, halbkugeligen Rosette aus vielen grau-braunen, fächerförmigen Hütchen über verzweigtem weißem Strunk suchen (Poren statt Lamellen). Nur jung und zart ernten. Verwechselbar mit Riesenporling (Meripilus giganteus, schwärzt auf Druck) und Eichhase (Polyporus umbellatus) – Wuchsbild, Porenschicht und Verfärbung prüfen.','123pilze, DGfM, SwissFungi; gängige Pilzführer',false),
('hemileccinum_impolitum','Sommer bis Frühherbst, Hauptzeit Juni–September (bis Oktober); wärmeliebend, erscheint einige Tage bis ~2 Wochen nach Regen in warmen Perioden um 18–25 °C. Profitiert stark von schwül-warmer Gewitterwitterung an thermophilen Standorten.','Warme, basen- bis kalkreiche, eher trockene Laubwaldböden; bevorzugt kalkige, sonnenexponierte Lagen.','Mykorrhiza v. a. mit Eiche (Quercus), auch Hainbuche und Rotbuche; typisch in lichten, warmen Eichen- und Laubmischwäldern sowie Parkanlagen auf Kalk. Eiche und warmer Kalkstandort als Zeiger.','mittel','Unter Eichen an warmen Kalkstandorten nach dem hellen, blass lederbraunen Röhrling mit gelben Poren und gelblichem, kaum oder nur schwach blauendem Fleisch suchen. Charakteristisch ist der jodartig-medizinische Geruch in der Stielbasis. Wie bei allen Röhrlingen Fleischverfärbung, Poren- und Stielmerkmale prüfen und blauende oder rotporige Arten sicher ausschließen.','123pilze, DGfM, SwissFungi; gängige Pilzführer',false),
('hericium_coralloides','Hauptzeit Sept–Okt (vereinzelt ab Aug bis Nov), ca. 1–2 Wochen nach feucht-kühler, regnerischer Witterung bei 8–15 °C. Fruchtet meist nur einmal pro Jahr am selben Totholzstamm, das Myzel kann aber über mehrere Jahre an derselben Stelle wiederkommen.','Standortunabhängig vom Mineralboden, da holzbewohnend; bevorzugt feuchte, schattige, luftfeuchte Lagen mit langsam vermoderndem Laubholz. Häufiger in luftfeuchten Buchen-Hangwäldern und entlang von Bachtälern.','Saprobiont (Holzzersetzer, kein Mykorrhiza-Partner) an liegendem und stehendem Totholz von Laubbäumen, vor allem Rotbuche (Fagus), seltener Esche, Ahorn, Eiche; sehr selten an Tanne. Zeigerstandort: alte, naturnahe Buchen-Mischwälder mit hohem Totholzanteil.','anfaenger','Charakteristisch ist der korallenartig verzweigte weisse Fruchtkörper mit kurzen (3–10 mm) Stacheln, die ausschliesslich an den herabhängenden Astenden sitzen. Verwechslung praktisch ausgeschlossen, es gibt keine giftigen Doppelgänger. An morschen liegenden Buchenstämmen und Ästen suchen, oft auf der Unterseite oder an Bruchstellen. Junge, rein weisse Exemplare ernten; vergilbte oder bräunliche sind überständig und bitter. Achtung: Stachelbärte sind in der Schweiz geschützt bzw. selten – nur massvoll und nur sicher bestimmt sammeln.','123pilze.de; SwissFungi (WSL); DGfM-Artbeschreibung; Breitenbach/Kränzlin Pilze der Schweiz',false),
('hericium_erinaceus','Hauptzeit Sept–Okt (bis in milde Novemberwochen), erscheint ca. 1–2 Wochen nach ergiebigen Niederschlägen bei kühlen 10–18 °C, meist im Spätsommer/Herbst. Bildet oft nur einen einzelnen grossen Fruchtkörper pro Baum, der über mehrere Wochen weiterwächst; kehrt jahrelang am selben Stamm wieder.','Holzbewohnend, daher mineralbodenunabhängig; gedeiht in luftfeuchten, warmen Laubwald-Lagen. Bevorzugt klimatisch begünstigte, eher tiefere Lagen mit alten, starken Laubbäumen.','Schwächeparasit und Saprobiont an lebenden, verletzten sowie toten alten Laubbäumen (Wundparasit), vor allem an Buche und alter Eiche, seltener Walnuss/Ahorn. Wächst typischerweise aus Stammwunden, Astabbrüchen oder Höhlungen in mehreren Metern Höhe. Zeigerstandort: alte Hutewälder, Parkbäume und naturnahe Laub-Altholzbestände.','anfaenger','Unverwechselbar: kompakter, kissenförmiger weisser Fruchtkörper mit langen (1–5 cm), bartartig herabhängenden Stacheln (Löwenmähne). Keine giftigen Doppelgänger. An Stammwunden und Astlöchern alter Buchen/Eichen Ausschau halten, oft in Augenhöhe bis mehrere Meter hoch. Nur frische, reinweisse Exemplare ernten; gelblich-bräunliche sind alt und zäh-bitter. In der Schweiz selten und schützenswert – nur einzeln und sicher bestimmt entnehmen.','123pilze.de; SwissFungi (WSL); DGfM-Artbeschreibung; Laux Der grosse Kosmos Pilzführer',false),
('hortiboletus_rubellus','Hauptzeit Juli–Sept (vereinzelt Juni und bis Okt), erscheint ca. 1 Woche nach warmem Sommerregen bei 16–22 °C. Wärmeliebend, schubweises Erscheinen nach Gewitterregen; gehört zu den ersten Sommer-Röhrlingen.','Mässig nährstoffreiche, oft eher trockenwarme, neutrale bis schwach saure Böden; verträgt verdichtete und gestörte Böden. Häufig an grasigen, sonnigen Standorten.','Mykorrhiza-Partner vor allem von Eiche (Quercus) und Linde (Tilia), auch Hainbuche und Rotbuche. Typisch an warmen, lichten Stellen: Waldränder, Parkrasen, Friedhöfe, Stadtparks, Alleen und Wegränder. Zeigerstandort: einzelstehende Eichen/Linden auf kurzem Rasen.','mittel','Kleiner Filzröhrling mit oliv-rotbraunem, oft feinrissigem Hut, leuchtend roter, fein gepunkteter Stieloberfläche und gelben Poren, die bei Druck blauen. Sicherstes Merkmal: im Stielbasis-Fleisch winzige karottenrote bis orangerote Pünktchen (nur längs aufschneiden!). Nur bedingt essbar (jung, gut durchgegart, kleine Mengen) und geschmacklich schwach – kein Sammelpilz für die Küche im grossen Stil. Schwammig-alte und madige Exemplare meiden. Verwechselbar mit anderen Filzröhrlingen, alle gelten als ungiftig, aber Bestimmung der Rotfuss-Gruppe erfordert Erfahrung.','123pilze.de; SwissFungi (WSL); DGfM; Gerhardt BLV Handbuch Pilze',false),
('hydnum_rufescens','Hauptzeit Aug–Okt (vereinzelt Juli und bis Nov), ca. 1–2 Wochen nach kräftigem Spätsommer-/Herbstregen bei 10–18 °C. Erscheint oft truppweise und in Hexenringen; relativ witterungsrobust und lange haltbar, da kaum madig.','Eher saure bis neutrale, humose und moosige Waldböden, frisch bis mässig feucht; oft an moosreichen, lichten Stellen.','Mykorrhiza-Partner von Laub- und Nadelbäumen (Buche, Eiche, Birke, Fichte). Typisch in lichten Wäldern, an grasig-moosigen Böschungen, Wegrändern und Lichtungen. Zeigerstandort: moosige Partien unter Buchen oder Fichten.','anfaenger','Stoppelpilze sind eine sichere Anfängergruppe: orange- bis rotbrauner, oft etwas trichteriger Hut und – statt Lamellen oder Röhren – weiche, weisslich-creme Stacheln (Stoppeln) an der Hutunterseite. Keine giftigen Doppelgänger; das Stachelmerkmal schliesst Verwechslung mit gefährlichen Lamellenpilzen aus. H. rufescens ist kleiner und kräftiger gefärbt als der Semmelstoppelpilz (H. repandum). Fleisch mild, im Alter leicht bitterlich – jüngere Exemplare bevorzugen. Madenfrei, daher gut zum Trocknen.','123pilze.de; SwissFungi (WSL); DGfM; Breitenbach/Kränzlin Pilze der Schweiz',false),
('hygrophorus_marzuolus','Sehr früh im Jahr: Hauptzeit Feb–April (lagenabhängig bis Mai), oft direkt am ausapernden Schneerand. Erscheint nach Schneeschmelze und ersten milderen Tagen bei knapp über 0 bis ca. 8 °C; wächst langsam und schubweise über mehrere Wochen, häufig noch halb von Laub/Schnee bedeckt.','Bevorzugt kalkhaltige, humose Bergwaldböden; frisch, an eher kühl-schattigen Nordhängen. Lagen meist ca. 300–1500 m.','Mykorrhiza-Partner von Nadelbäumen, vor allem Weisstanne (Abies alba) und Fichte (Picea abies), auch Kiefer; teils unter Rotbuche im Bergmischwald. Zeigerstandort: kalkreiche Tannen-/Fichten-Bergwälder, oft in Moos- und Nadelstreu nahe Schneeresten, der Pilz drückt sich häufig nur halb durch die Streu.','mittel','Fleischiger, robuster Schneckling mit anfangs weisslichem, später grau bis schiefergrau geflecktem, schmierig-glattem Hut, weissen, dicklichen, weit stehenden Lamellen und weissem Fleisch. Wächst fast verborgen unter Laub/Nadelstreu – auf kleine Erdaufwölbungen achten. Guter Speisepilz, aber zur Erscheinungszeit (Vorfrühling) kaum Verwechslungs-Konkurrenz; dennoch graue Hutfarbe, weisse Lamellen und Tannen-/Kalkstandort gemeinsam prüfen. Nicht mit grauen Ritterlingen verwechseln. Standorttreu: gute Stellen jährlich wieder absuchen.','123pilze.de; SwissFungi (WSL); DGfM; Breitenbach/Kränzlin Pilze der Schweiz',false),
('lactarius_rufus','Hauptzeit Aug–Okt (bis Nov), ca. 1–2 Wochen nach ergiebigem Spätsommer-/Herbstregen bei 10–16 °C. Erscheint oft in grossen Trupps und über mehrere Wochen; einer der häufigsten Milchlinge saurer Nadelwälder.','Ausgesprochen saure, nährstoffarme, oft sandig-torfige oder moorige Böden; frisch bis feucht. Häufig in Heidelbeer- und Torfmoos-Beständen.','Mykorrhiza-Partner von Nadelbäumen (Kiefer, Fichte, Tanne) und Birke. Zeigerstandort: bodensaure Kiefern-/Fichtenwälder, Moorränder, oft zwischen Heidelbeere (Vaccinium) und Torfmoos (Sphagnum). Zeigerpflanzen: Heidelbeere, Drahtschmiele, Torfmoos deuten den passenden sauren Standort an.','mittel','Rotbrauner, trichterig vertiefter Hut mit kleinem Buckel (Papille), bräunlicher Stiel; beim Anschneiden tritt reichlich weisse, unveränderliche Milch aus, die sehr scharf (paprika-/pfefferscharf) schmeckt – daher Name Paprikapilz. Nur bedingt essbar: roh giftig/scharf, essbar erst nach Abbrühen/gründlichem Garen, meist als Mischpilz oder Würzpilz. Scharfe Milch + saurer Nadelwald-Standort = gutes Erkennungsmerkmal. Verwechselbar mit anderen rotbraunen Milchlingen; mild schmeckende Milchlinge nicht damit verwechseln. Geschmacksprobe (Milch auf die Zunge, danach ausspucken) hilft bei der Abgrenzung.','123pilze.de; SwissFungi (WSL); DGfM; Gerhardt BLV Handbuch Pilze',false),
('lactarius_salmonicolor','Hauptzeit September–Oktober (vereinzelt ab Juli bis November), schubweise ca. 1–2 Wochen nach ergiebigem Landregen bei milden 10–18 °C. Erscheint nach feucht-warmen Spätsommerwochen oft gleichzeitig mit anderen Edelreizkern; auf höheren Tannenlagen entsprechend später.','Frische, basen- und nährstoffreiche, eher kalkhaltige Waldböden; mässig feucht, gut durchlüftet. Meidet stark saure, magere Standorte.','Mykorrhiza ausschliesslich mit der Weisstanne (Abies alba); in Tannen- und Tannen-Buchenwäldern, gern an feuchteren, moosigen Stellen und Hangfüssen. Zeiger: reine Tannenbestände bzw. tannenreicher Bergmischwald.','mittel','Auf orange gezonten Hut mit eingerolltem Rand und auf die orange Milch achten, die langsam weinrötlich verfärbt – ohne Grünfleckung. Nur unter Weisstanne suchen; ohne Tanne in der Nähe ist es nicht der Lachsreizker. Speisewert mässig (kann leicht bitter sein), am besten jung und kräftig anbraten. Verwechslung mit anderen orangemilchenden Reizkern (Edelreizker-Gruppe) ist harmlos, aber Standort und Milchfarbe trennen sicher.','123pilze, SwissFungi (Verbreitung Abies alba), DGfM; Pilzführer Gminder/Laux',false),
('lactarius_torminosus','Hauptzeit August–Oktober (ab Juli möglich), schubweise rund 1–2 Wochen nach kräftigem Regen bei 12–18 °C. Tritt in feucht-milden Spätsommer-/Herbstphasen oft truppweise unter Birken auf.','Saure, eher trockene bis mässig feuchte, magere Böden; auch auf verdichteten, sandigen Wegrändern und Ruderalflächen.','Mykorrhiza mit Birke (Betula); an Birken in Wäldern, an Wald- und Wegrändern, in Parks und Gärten. Zeiger: junge Birken auf saurem, lichtem Boden.','experte','Kennzeichnend ist der stark zottig-bärtige, eingerollte Hutrand und die blass rosa-orange Hutfarbe; die weisse Milch ist scharf und bleibt weiss. Nur bedingt essbar – roh giftig/magen-darm-reizend, in einigen Regionen nur nach gründlichem Abbrühen verwendet; für Einsteiger nicht empfohlen. Vom essbaren Lachs-/Edelreizker durch weisse (nicht orange) Milch und den bärtigen Rand sicher zu trennen. Im Zweifel stehen lassen.','123pilze, DGfM (bedingt essbar/roh giftig), SwissFungi; Pilzführer Laux',false),
('lepista_saeva','Späte Art: Hauptzeit Oktober–November (bis in milde Dezembertage), oft erst nach den ersten kühlen Nächten und Nebel-/Tauphasen, ca. 1–2 Wochen nach Regen bei 5–12 °C. Verträgt leichte Nachtfröste und erscheint in Hexenringen.','Nährstoffreiche, kalkhaltige bis neutrale Wiesen- und Weideböden; mässig feucht, gut gedüngte Grasflächen bevorzugt.','Kein Mykorrhizapilz – Streu-/Bodensaprobiont auf Wiesen, Weiden, in Parks, an Waldrändern und Lichtungen; bildet auffällige Hexenringe. Zeiger: ältere, ungespritzte Magerwiesen und Viehweiden.','mittel','Markant ist der lila bis violett gefärbte, faserige Stiel unter einem blass lederbraunen, kahlen Hut mit blassrosa-lila, gedrängten Lamellen; Geruch angenehm. Auf Wiesen wachsend, nicht im Wald – das hilft, ihn von violetten Wald-Schleierlingen (Cortinarius, teils giftig) zu trennen, die ein Cortina-Velum und rostbraunes Sporenpulver haben. Lepista hat kein Velum und blassrosa Sporenpulver. Spät im Jahr in Ringen suchen.','123pilze, DGfM, SwissFungi; Pilzführer Gminder',false),
('lyophyllum_decastes','Lange Saison mit Schwerpunkt September–November, kleinere Schübe schon im Frühjahr (April–Mai) möglich. Erscheint büschelig ca. 1–2 Wochen nach Regen bei 10–18 °C, gern auf gestörten, frisch bearbeiteten Böden.','Lockere, humusreiche, nährstoffreiche Böden; frische bis feuchte, oft gestörte Standorte (Erdaufschüttungen, Wegränder).','Saprobiont – kein Baumpartner; in dichten Büscheln an Wegrändern, auf Wiesen, in Laub- und Mischwäldern, Parks und auf Erdaufschüttungen. Zeiger: frisch aufgeschütteter oder verdichteter, humoser Boden.','experte','Wächst in dichten, verwachsenen Büscheln mit grau- bis ockerbraunen, glatten Hüten, weisslichen gedrängten Lamellen, faserigem Stiel ohne Ring und mildem Geruch/Geschmack. Achtung: büschelig wachsende Arten sind heikel – Verwechslung mit dem giftigen Riesen-Rötling (Entoloma sinuatum, rosa Sporenpulver) und anderen ist möglich. Sporenpulver weiss prüfen und nur bei sicherer Bestimmung sammeln; für Anfänger nicht geeignet.','123pilze, DGfM, SwissFungi; Pilzführer Laux/Gminder',false),
('macrolepiota_mastoidea','Hauptzeit August–Oktober (bis November), einzeln bis in kleinen Gruppen ca. 1–2 Wochen nach ausgiebigem Regen bei 12–20 °C. Bevorzugt warme Spätsommer-/Herbstphasen an lichten, grasigen Stellen.','Kalkhaltige, nährstoffreiche, eher trocken-warme Böden; lichte, grasige Standorte.','Saprobiont der Streu; in lichten Laub- und Mischwäldern, an Wald- und Wegrändern, auf Heiden, in Parks und Gärten. Zeiger: warme, kalkreiche Säume und Lichtungen.','mittel','Schirmpilz-Typ mit deutlich vorgezogenem, spitzem Buckel („Zitze") auf hell genattertem Hut, schlankem genattertem Stiel und verschiebbarem Ring; Fleisch verfärbt sich kaum. Wie alle Riesenschirmlinge nur den grossen, hochwüchsigen Schirmling sammeln – kleine Schirmlinge (Lepiota) und der giftige Garten-Safranschirmling (Chlorophyllum) sind gefährliche Verwechsler. Auf den verschiebbaren Ring und die deutliche Zitze achten; Stielbasis ohne Knolle/Scheide.','123pilze, DGfM, SwissFungi; Pilzführer Gminder/Laux',false),
('meripilus_giganteus','Hauptzeit Juli–Oktober (bis November), als grosse Rosette über mehrere Wochen am selben Stamm wachsend; Frischschub typischerweise nach feucht-warmen Phasen und Regen bei 14–22 °C. Erscheint mehrjährig wiederkehrend am gleichen Wurzelbereich.','Standort vom Wirtsbaum bestimmt; nährstoffreiche, feuchte Wald- und Parkböden im Wurzelbereich alter Laubbäume.','Saprobiont/Schwächeparasit – kein Mykorrhizapilz; wächst in grossen, fächerigen Büscheln an der Stammbasis und über den Wurzeln alter Buchen, auch an Eiche, Linde, Rosskastanie, in Wäldern und Parks. Zeiger: alte, kränkelnde Laubbäume und deren Wurzelanläufe.','anfaenger','Sehr auffällig und kaum zu verwechseln: riesige, fächerförmige Rosette aus vielen weich-fleischigen Hüten an der Basis alter Buchen; Unterseite mit feinen Poren (keine Lamellen), Fleisch verfärbt sich bei Druck/Schnitt schwärzlich. Nur ganz junge, zarte Randteile sind essbar (gekocht), ältere werden zäh und sind von mässigem Speisewert. Wegen Schwärzung und Poren leicht von Lamellenpilzen zu unterscheiden – ein guter Anfänger-Erkennungspilz, aber kein hochwertiger Speisepilz.','123pilze, DGfM, SwissFungi; Pilzführer Laux',false),
('phallus_impudicus','Hauptzeit Juli–Oktober, einzelne Exemplare schon ab Juni; das Stadium «Hexenei» erscheint schubweise einige Tage nach feucht-warmer Witterung und reckt sich bei 15–20 °C oft innert weniger Stunden zum reifen Fruchtkörper – die Reife ist also extrem schnell.','Humusreiche, nährstoffreiche, gut durchfeuchtete Böden; weitgehend bodenvag, sowohl auf saurem als auch kalkhaltigem Untergrund, gern bei morschem Holz im Boden.','Saprobiont (kein Mykorrhiza-Partner) auf vergrabenem Totholz und Holzhäcksel; in Laub-, Nadel- und Mischwald, Auwald, Parkanlagen und Gebüschen, häufig nahe Stümpfen und unter Brennnesseln/Holunder als Nährstoffzeiger.','mittel','Der reife Pilz ist am penetranten Aasgeruch und der grünlich-schleimigen, fliegenbesetzten Hutkappe schon aus Distanz unverwechselbar. Essbar (mild) ist nur das junge «Hexenei»: weiss, elastisch-prall, eiergross. VOR der Verwendung längs aufschneiden – innen muss eine grünlich-olive Gallertschicht über einer weissen, gallertigen Innenstruktur liegen. Eier mit weiss-lamelligem Anschnitt liegenlassen: das könnte ein junger, tödlicher Knollenblätterpilz (Amanita) sein.','123pilze.de; DGfM-Artporträt; SwissFungi (WSL); Standard-Pilzführer (Laux, Gerhardt)',false),
('pluteus_cervinus','Lange Saison von April bis November mit Schwerpunkt im Frühsommer und Herbst; erscheint büschelig bis einzeln einige Tage nach Regen, sobald das Substrat durchfeuchtet ist, und ist weniger temperaturkritisch als Mykorrhizapilze – auch in milderen Phasen aktiv.','Wächst direkt auf dem Substrat, nicht im Mineralboden; bevorzugt feuchtes, morsches Laubholz, ist aber bodenvag bezüglich pH.','Saprobiont auf morschem Laubholz: Baumstümpfe, liegende Stämme, vergrabenes Holz, Sägemehl- und Holzlagerplätze; in Laub- und Mischwäldern, gern an Buche und Pappel.','mittel','Erkennungsmerkmale: anfangs weisse, frei stehende Lamellen, die durch das rosa Sporenpulver bald fleischrosa werden (Sporenabwurf rosabraun), brauner, oft radialfaseriger Hut, Geruch leicht rettichartig, KEIN Ring und KEINE Knolle. Die freien, rosa Lamellen plus Wuchs auf Holz trennen ihn von braunhütigen Risspilzen/Trichterlingen. Wegen der rosa Lamellen unbedingt von jungen, weisslamelligen Knollenblätterpilzen unterscheiden – diese wachsen am Boden und haben Ring und Knolle.','123pilze.de; DGfM-Artporträt; SwissFungi (WSL); Standard-Pilzführer (Laux, Gerhardt)',false),
('ramaria_botrytis','Hauptzeit August–Oktober (vereinzelt bis November); erscheint im Spätsommer/Frühherbst meist 1–2 Wochen nach ergiebigen Regenfällen bei milden 12–18 °C, oft an denselben Stellen wiederkehrend.','Kalkreiche bis basenreiche, eher trockene bis frische Laubwaldböden; meidet stark saure Standorte.','Mykorrhizapilz vor allem mit Rotbuche (Fagus) und Eiche (Quercus) in wärmebegünstigten Laub- und Mischwäldern, häufig an Hängen und Waldrändern auf Kalk.','experte','Blumenkohlartig dicht verzweigte, weisslich-cremefarbene Koralle mit charakteristisch rosa bis weinrot gefärbten Astspitzen und dickem, fleischigem Strunk. Nur jung und fest essbar; ältere, weiche oder bitter werdende Stücke und solche mit gelben Spitzen meiden. Korallen sind generell heikel: einige gelb-/ockerspitzige und bittere Ramaria-Arten wirken abführend. Im Zweifel stehen lassen – ohne sichere Gattungs- und Artkenntnis nicht sammeln.','123pilze.de; DGfM-Artporträt; SwissFungi (WSL); Standard-Pilzführer (Laux, Gerhardt)',false),
('russula_aurea','Hauptzeit Juli–September (Randmonate Juni und Oktober); erscheint einzeln einige Tage bis ~1 Woche nach warmen Sommerregen bei 15–20 °C, bevorzugt in wärmeren Phasen wärmebegünstigter Laubwälder.','Eher basenreiche bis neutrale, oft kalkbeeinflusste, frische Laubwaldböden in wärmebegünstigter Lage.','Mykorrhizapilz vor allem mit Rotbuche (Fagus) und Eiche (Quercus), seltener bei Nadelbäumen; in warmen Laub- und Mischwäldern, gern an lichten, südexponierten Hängen.','experte','Auffällig durch leuchtend roten Hut, dazu goldgelb getönte Lamellenschneiden und gelblichen Stiel; Fleisch mild (kein scharfer Geschmack), Sporenpulver dottergelb. Diese Merkmalskombination ist für einen Täubling recht markant, dennoch ist die Gattung Russula artenreich und schwierig. Grundregel zur Sicherheit: nur milde, nicht scharf schmeckende Täublinge gelten als essbar – eine Geschmacksprobe (Stück kauen, ausspucken) hilft, scharfe Arten auszuschliessen. Sichere Artbestimmung nur mit Erfahrung.','123pilze.de; DGfM-Artporträt; SwissFungi (WSL); Standard-Pilzführer (Laux, Gerhardt)',false),
('russula_paludosa','Hauptzeit Juli–Oktober; erscheint nach sommerlichen bis herbstlichen Regenphasen, sobald die feuchten Moorränder durchnässt sind, schubweise bei 12–18 °C – einer der ergiebigeren Speisetäublinge höherer, feuchter Nadelwaldlagen.','Saure, dauerfeuchte bis nasse, torfige Böden; an Moorrändern, Hochmoorrändern und in feuchten Nadelwäldern höherer Lagen.','Mykorrhizapilz mit Kiefer (Pinus) und Fichte (Picea); in Moorwäldern, an Torfmoospolstern und entlang vernässter Nadelwaldsenken, oft bei Heidelbeere und Torfmoos als Zeigern.','experte','Grosser, fester Täubling mit blutrotem bis rosarotem, oft mittig blasserem Hut, weissem Stiel mit zartem Rosaton, cremefarbenen Lamellen und blassgelbem Sporenpulver; Geschmack mild bis höchstens leicht schärflich. Standort (saure Moorränder, Kiefer/Fichte) ist ein gutes Indiz. Auch hier gilt die Täublings-Sicherheitsregel: nur milde Arten verwenden, scharf schmeckende verwerfen. Artbestimmung in der schwierigen Gattung Russula nur mit Erfahrung.','123pilze.de; DGfM-Artporträt; SwissFungi (WSL); Standard-Pilzführer (Laux, Gerhardt)',false),
('russula_xerampelina','Hauptzeit Juli–Oktober mit Schwerpunkt im Spätsommer/Frühherbst; erscheint einige Tage bis ~1 Woche nach ergiebigem Regen bei 12–18 °C, schubweise unter Fichte und Kiefer vom Tiefland bis zur Waldgrenze.','Eher saure, frische bis mässig feuchte Nadelwaldböden; weit verbreitet, vom Tiefland bis in höhere Lagen.','Mykorrhizapilz mit Fichte (Picea abies) und Kiefer (Pinus); in Nadel- und Mischwäldern, häufig im Fichtenmoos und entlang von Waldwegen.','experte','Das namensgebende Hauptmerkmal ist der Heringsgeruch (nach altem Fisch/Krabben), der im Alter und beim Trocknen stärker wird; Hut weinrot bis purpurbraun, Stiel beim Reiben/Altern gilbend bis bräunend, Fleisch mild, Sporenpulver ockergelb. Eine Tüpfelprobe mit Eisensulfat (FeSO4) färbt das Fleisch typisch grünlich – ein gutes Bestätigungsmerkmal. Wie bei allen Täublingen: nur milde, nicht scharfe Exemplare verwenden; sichere Artbestimmung erfordert Erfahrung in der Gattung Russula.','123pilze.de; DGfM-Artporträt; SwissFungi (WSL); Standard-Pilzführer (Laux, Gerhardt)',false),
('stropharia_rugosoannulata','Hauptzeit Juni und September–November, mit kleinerem Frühschub ab Mai; erscheint schubweise rund 1–2 Wochen nach kräftigem Regen bei mildem Wetter (ca. 12–20 °C). Reagiert stark auf frisch ausgebrachtes Holzhäcksel/Stroh und kann bis zum ersten strengen Frost fruchten.','Nährstoffreiche, humose, eher feuchte Böden; gedeiht bevorzugt auf zersetzendem organischem Material (Holzschnitzel, Stroh, Kompost). Bodenreaktion wenig kritisch (neutral bis leicht sauer), entscheidend ist frisches Häcksel-/Streusubstrat.','Kein Mykorrhizapilz, sondern saprob auf totem Pflanzenmaterial: Holzhäcksel-Beete, Rindenmulch, Strohballen, Komposthaufen, Ruderalstellen und Wegränder. Häufig in Gärten und auf Kulturbeeten (verbreiteter Speise-Kulturpilz).','anfaenger','Gezielt frisch gemulchte Beete, Rindenmulch-Flächen und Strohballen in Gärten/Parks absuchen. Erkennungsmerkmale: kräftiger, fleischiger Fruchtkörper mit rotbraun bis graubraun gefärbtem Hut, weisslich-grauem Stiel und auffallend dickem, oberseits gefurchtem (sternförmig gerieftem) Ring; Lamellen jung blass, im Alter purpur-graubraun durch das Sporenpulver. Verwechslungsarme Art, da kaum giftige Doppelgänger im selben Mulch-Habitat – im Zweifel Sporenpulverfarbe (dunkel purpurbraun) prüfen.','123pilze; DGfM; SwissFungi; gängige Pilzführer (Laux, Gerhardt)',false),
('suillellus_luridus','Hauptzeit Juli–Oktober (vereinzelt ab Juni); erscheint einige Tage bis ~2 Wochen nach durchdringenden Sommer-/Herbstregen bei warmen Bodentemperaturen (ca. 15–22 °C). Wärmeliebend, daher in milden Lagen früh und schubweise.','Bevorzugt basen-/kalkreiche, eher trockenwarme Böden; meidet stark saure Standorte. Gut drainierte, oft lehmig-kalkige Waldböden.','Mykorrhizapilz an Laubbäumen, v. a. Eiche, Buche, Linde und Hainbuche; auch in Parks, Alleen und an Wegrändern. Zeigerstandort sind kalkreiche, lichte Laub-/Mischwälder.','experte','Wärmebegünstigte Kalk-Laubwälder mit Eiche/Buche/Linde absuchen. Bestimmungsmerkmale: rotes bis orangerotes Röhrenmündungs-Netz nicht – wichtig ist das deutliche rote Netz auf dem Stiel, gelbes Fleisch das beim Anschnitt rasch tiefblau anläuft, sowie meist orangerote Poren. Achtung: bedingt essbar – nur gut durchgegart geniessbar, roh giftig, Alkoholunverträglichkeit möglich. Streng abzugrenzen vom giftigen Satans-Röhrling (Rubroboletus satanas, blasser Hut, schmieriger Geschmack) und anderen rotporigen Röhrlingen; nur für erfahrene Sammler. Verlässlich ist die Bourgeois-Linie (rötlicher Strich zwischen Röhrenboden und Hutfleisch).','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt)',false),
('suillus_bovinus','Hauptzeit August–Oktober (Randmonate Juni/Juli und November möglich); fruchtet gut 1–2 Wochen nach ergiebigem Regen bei 10–18 °C, oft truppweise und gesellig bis in den Spätherbst.','Saure, sandige, nährstoffarme und meist eher trockene Böden; typisch für podsolige Kiefernstandorte, Heiden und Moorränder.','Mykorrhizapilz fast ausschliesslich mit Kiefer (v. a. Wald-Kiefer); auf sandigen Kiefernwäldern, Heiden und in Moornähe. Häufig vergesellschaftet mit dem Rosenroten Gelbfuss (Gomphidius roseus) als Begleiter.','mittel','In lichten Kiefernwäldern auf Sandboden suchen, gern an Wegrändern und moosigen Stellen. Merkmale: ocker- bis ledergelber, schmieriger Hut, weit herablaufende, grob-eckige, olivgelbe bis bräunliche Poren (nicht fein wie beim Steinpilz), zäh-elastisches Fleisch, das schwach rötlich/bräunlich verfärben kann. Speisewert gering (weicher, im Alter mehliger Pilz) – jung sammeln. Verwechslung v. a. mit anderen Schmierröhrlingen (Suillus); keine gefährlich giftigen Doppelgänger, aber Sandkiefer-Bindung als Bestätigung nutzen.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt)',false),
('tricholoma_columbetta','Hauptzeit August–Oktober (bis November in milden Lagen); erscheint einige Tage bis ~2 Wochen nach ergiebigem Spätsommer-/Herbstregen bei 10–16 °C, meist in kleinen Gruppen.','Saure bis schwach saure Sand- und Silikatböden; bevorzugt mässig frische, nährstoffärmere Standorte.','Mykorrhizapilz an Laubbäumen, vor allem Buche und Eiche, in Laub- und Mischwäldern auf Sauerböden. Zeigerstandort sind bodensaure Buchen-/Eichenwälder.','mittel','In bodensauren Buchen-/Eichenwäldern nach rein weissen Ritterlingen suchen. Merkmale: reinweisser, seidig-faseriger, oft glänzender Hut (im Alter teils mit blau-grünlichen oder rötlichen Flecken), weisse Lamellen, mehlig-gurkiger Geruch, milder Geschmack. Abzugrenzen von giftigen weissen Trichterlingen/Risspilzen (Lamellen herablaufend bzw. brauner Sporenstaub) und vom scharf/seifig riechenden Tigerritterling-Umfeld – im Zweifel die seidige Hutoberfläche und der milde Geschmack als Hinweis nutzen.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt)',false),
('tricholoma_portentosum','Hauptzeit September–November, in milden Wintern bis Dezember/Januar; einer der spätesten Speisepilze. Fruchtet rund 1–2 Wochen nach Herbstregen bei kühlen 5–12 °C und ist relativ frosttolerant.','Saure, sandige bis moosige, nährstoffarme Böden; typisch für podsolige Nadelwaldstandorte.','Mykorrhizapilz mit Nadelbäumen (v. a. Fichte und Kiefer), gelegentlich auch bei Espe/Birke; in moosigen Nadel- und Mischwäldern. Oft halb im Moos oder unter Nadelstreu verborgen.','mittel','Spät im Jahr in moosigen Kiefern-/Fichtenwäldern suchen, häufig nur die graue Hutkuppe aus Moos/Streu ragend. Merkmale: schmutzig-grauer, radialfaseriger (schwarzfaserig streifiger), schmieriger Hut, weissliche bis blassgelbliche Lamellen, im Stiel und Fleisch oft zart gelblicher Ton, milder Geschmack. Abzugrenzen vom giftigen Tiger-Ritterling (Tricholoma pardinum, graue Schuppen, mehliger Geruch, robuster) und vom bitteren Brennenden Ritterling (T. virgatum, spitzgebuckelt, scharf) – mild schmeckend und gelblicher Ton sprechen für portentosum.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt)',false)
